// Central asset manifest. Components ask for an AssetKey, never a filename.
// Web copies are generated by `npm run assets` from scripts/asset-sources.json,
// which maps each ID below to the untouched original in ../Birthday.
import dims from './assetDimensions.json';
import type { AssetKey, Photo } from './types';

