const BASE = `${import.meta.env.BASE_URL}assets/photos/`;
const table = dims as Record<string, { file: string; w: number; h: number }>;

/** Returns null when the file hasn't been generated yet; callers show a placeholder. */
export function photo(key: AssetKey): Photo | null {
  const d = table[selectedAssets[key]];
  if (!d) return null;
  return {
    key,
    src: `${BASE}${d.file}.webp`,
    thumb: `${BASE}${d.file}_thumb.webp`,
    width: d.w,
    height: d.h,
    ...details[key],
  };
}

export function photos(keys: AssetKey[]): Photo[] {
  return keys.map(photo).filter((p): p is Photo => p !== null);
}

